struct DocOutcome {
    exit_code: i32,
    stdout: String,
    stderr: String,
}

async fn cmd_output(cmd: &mut Command) -> DocOutcome {
    match cmd.output().await {
        Ok(o) => DocOutcome {
            exit_code: o.status.code().unwrap_or(-1),
            stdout: String::from_utf8_lossy(&o.stdout).to_string(),
            stderr: String::from_utf8_lossy(&o.stderr).to_string(),
        },
        Err(e) => DocOutcome {
            exit_code: -1,
            stdout: String::new(),
            stderr: format!("Failed to spawn: {e}"),
        },
    }
}

async fn run_pandoc(input_format: &str, input_file: &PathBuf, output_path: &PathBuf) -> Result<DocOutcome, String> {
    let mut cmd = Command::new("pandoc");
    cmd.arg("--from").arg(input_format);
    cmd.arg(input_file).arg("-o").arg(output_path);
    Ok(cmd_output(&mut cmd).await)
}

async fn run_pdflatex(input_file: &PathBuf, stem: &str, output_path: &PathBuf) -> Result<DocOutcome, String> {
    let out_dir = std::env::temp_dir();
    let run = || async {
        let mut cmd = Command::new("pdflatex");
        cmd.arg("-interaction=nonstopmode")
            .arg(format!("-output-directory={}", out_dir.to_string_lossy()))
            .arg(format!("-jobname={stem}"))
            .arg(input_file);
        cmd_output(&mut cmd).await
    };
    // Two passes so references/TOC settle.
    let first = run().await;
    let second = run().await;
    let mut outcome = DocOutcome {
        exit_code: second.exit_code,
        stdout: format!("{}\n{}", first.stdout, second.stdout),
        stderr: format!("{}\n{}", first.stderr, second.stderr),
    };
    // Move the generated PDF to the requested location.
    let generated = out_dir.join(format!("{stem}.pdf"));
    if outcome.exit_code == 0 {
        if let Err(e) = fs::copy(&generated, output_path) {
            outcome.exit_code = -1;
            outcome.stderr.push_str(&format!("\nFailed to copy PDF to destination: {e}"));
        }
    }
    let _ = fs::remove_file(&generated);
    Ok(outcome)
}

async fn run_typst(input_file: &PathBuf, output_path: &PathBuf) -> Result<DocOutcome, String> {
    let mut cmd = Command::new("typst");
    cmd.arg("compile").arg(input_file).arg(output_path);
    Ok(cmd_output(&mut cmd).await)
}